// Thunderstorm: dark rolling clouds + random lightning strikes with branches.
// All per-LED maths in fixed point; strikes/leaders precomputed in update().
uniform float speed : 0.1 .. 5.0 = 1.0;     // storm intensity: strikes per second
uniform float flash : 0.2 .. 3.0 = 1.2;     // flash duration (s)
uniform vec3 tint : color = 0.55, 0.7, 1.0; // lightning tint

state fixed cloudPh;      // cloud drift phase (turns)
state fixed pulsePh;      // slow brightness breathing (turns)
state fixed flashEnv;     // flash envelope 0..1 (fixed)
state float flashT;       // seconds since strike start
state float nextStrike;   // seconds until next strike
state int strikeLed;      // LED index of the strike
state int branchLed;      // LED index of the branch point
state int branchDir;      // +1 / -1 branch direction
state bool hasBranch;
state bool flashOn;
state bool inited;

void update() {
  if (!inited) {
    cloudPh = fixed(hash(1.7));
    pulsePh = fixed(0.0);
    flashEnv = fixed(0.0);
    flashT = 1e9;
    nextStrike = 0.5 + hash(3.1) * 2.0;
    strikeLed = 0;
    branchLed = 0;
    branchDir = 1;
    hasBranch = false;
    flashOn = false;
    inited = true;
  }
  // cloud drift + breathing (fixed phases in TURNS)
  cloudPh = fract(cloudPh + fixed(dt * speed * 0.02));
  pulsePh = fract(pulsePh + fixed(dt * speed * 0.05));

  if (flashOn) {
    flashT = flashT + dt;
    if (flashT > flash) {
      flashOn = false;
      flashEnv = fixed(0.0);
      nextStrike = 0.4 + hash(float(frame) * 0.37) * (2.5 / max(speed, 0.1));
    } else {
      // double-strobe envelope: sharp attack, two pulses, decay
      float t = flashT / flash;
      float e = exp(-t * 6.0) + exp(-abs(t - 0.35) * 18.0) * 0.8;
      flashEnv = fixed(min(e, 1.0));
    }
  } else {
    nextStrike = nextStrike - dt;
    if (nextStrike <= 0) {
      flashOn = true;
      flashT = 0.0;
      strikeLed = int(hash(float(frame) * 7.3) * 500.0);
      hasBranch = hash(float(frame) * 3.9) > 0.4;
      branchLed = strikeLed + int(hash(float(frame) * 5.1) * 80.0) - 40;
      branchDir = hash(float(frame) * 9.7) > 0.5 ? 1 : -1;
      if (branchLed < 0) { branchLed = 0; }
      if (branchLed > 499) { branchLed = 499; }
    }
  }
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);          // 0..1 along the helix
  fixed y = fixed(led.pos.y);      // height
  fixed idx = fixed(led.idx);

  // --- dark rolling clouds: two drifting sine bands + height gradient ---
  fixed band1 = sin(s * fixed(6.0) + cloudPh);
  fixed band2 = sin(s * fixed(13.0) - cloudPh * fixed(1.7) + y * fixed(4.0));
  fixed cloud = band1 * fixed(0.5) + band2 * fixed(0.35) + y * fixed(0.4);
  cloud = clamp(cloud * fixed(0.5) + fixed(0.35), fixed(0.0), fixed(1.0));
  fixed breathe = sin(pulsePh * fixed(6.2832)) * fixed(0.08) + fixed(0.92);
  fixed grey = cloud * breathe * fixed(0.16);   // very dark cloud base

  // --- lightning: bright channel at strikeLed, decaying with helix distance ---
  fixed d = abs(idx - fixed(strikeLed));
  fixed chan = clamp(fixed(1.0) - d * fixed(0.06), fixed(0.0), fixed(1.0));
  fixed chan2 = chan * chan;
  fixed leader = chan2 * flashEnv * fixed(1.4);

  // branch: a second fainter channel offset from the strike
  fixed bd = abs(idx - fixed(branchLed));
  fixed bchan = clamp(fixed(1.0) - bd * fixed(0.09), fixed(0.0), fixed(1.0));
  fixed branch = bchan * bchan * flashEnv * fixed(0.5) * (hasBranch ? fixed(1.0) : fixed(0.0));

  fixed lum = grey + leader + branch;
  lum = clamp(lum, fixed(0.0), fixed(1.0));

  // cold blue-white flash tint on the leader, grey-blue clouds otherwise
  fixed3 col = hsv2rgb(fixed(0.58), fixed(0.35), lum);
  fixed3 flashCol = hsv2rgb(fixed(0.55), fixed(0.15), lum);
  fixed isFlash = step(fixed(0.05), flashEnv);
  return mix(col, flashCol, isFlash * float(flashEnv));
}

